import json, os, pathlib, sys
app_dir = pathlib.Path(os.environ["AUTARK_APP_DIR"])

def secret(name):
    path = os.environ.get(name, "").strip()
    if not path:
        return ""
    try:
        return pathlib.Path(path).read_text(encoding="utf-8-sig").strip()
    except OSError:
        return ""

exe = os.environ.get("AUTARK_PG0_EXE", "")
if exe and pathlib.Path(exe).is_file():
    os.environ["PG0_EXECUTABLE"] = exe
from pg0 import Pg0, Pg0AlreadyRunningError
pg = Pg0(name="mira", port=int(os.environ.get("AUTARK_MIRA_PG0_PORT", "55432")), database="mira")
try:
    info = pg.start()
except Pg0AlreadyRunningError:
    info = pg.info()
os.environ["DATABASE_URL"] = info.uri
model = os.environ.get("AUTARK_MIRA_LLM_MODEL", "").strip()
base = os.environ.get("AUTARK_MIRA_LLM_BASE_URL", "").strip()
config = pathlib.Path(os.environ["AUTARK_MIRA_CONFIG"])
config.parent.mkdir(parents=True, exist_ok=True)
lines = ["llm:"]
if model:
    lines.append("  model: " + json.dumps(model))
if base:
    lines.append("  base_url: " + json.dumps(base))
if len(lines) > 1:
    config.write_text("\n".join(lines) + "\n", encoding="utf-8")
else:
    config = None
key = secret("AUTARK_MIRA_KEY_FILE")
if key:
    os.environ["OPENROUTER_API_KEY"] = key
admin = secret("AUTARK_MIRA_ADMIN_PASSWORD_FILE")
if admin:
    os.environ["ADMIN_PASSWORD"] = admin
if config is not None:
    from mira.config import set_global_defaults
    set_global_defaults(str(config))
app_id = os.environ.get("AUTARK_MIRA_GITHUB_APP_ID", "").strip()
github_key = secret("AUTARK_MIRA_GITHUB_KEY_FILE") if app_id else ""
webhook = secret("AUTARK_MIRA_WEBHOOK_SECRET_FILE")
from mira.platforms.github.auth import GitHubAppAuth
from mira.platforms.server import create_app
auth = None
if app_id and github_key:
    auth = GitHubAppAuth(app_id=app_id, private_key=github_key)
bot_name = "miracodeai"
if auth is not None:
    import asyncio
    try:
        detected = asyncio.run(auth.get_bot_identity())
    except Exception:
        detected = None
    if detected and all(c.isascii() and (c.isalnum() or c in "_-") for c in detected):
        bot_name = detected
application = create_app(app_auth=auth, webhook_secret=webhook if auth is not None else None, bot_name=bot_name)
if auth is not None:
    try:
        from mira.dashboard.api import _app_db
        _app_db.set_setting("bot_name", bot_name)
    except Exception:
        pass
import uvicorn
uvicorn.run(application, host="127.0.0.1", port=int(sys.argv[1]))
